function jf_serveyTypeChoice(opt){
	tabNumber = opt;
	if(opt == '1'){
		$('.set1').show();
		$('.set2').hide();
		$('.set3').hide();
		$('.set4').hide();
		$('.set5').hide();
	}else if(opt == '2'){
		$('.set1').hide();
